#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("ciag.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int maxLen = 1, maxStart = 0;
    string maxTyp = "";
    int incLen = 1, incStart = 0;
    int decLen = 1, decStart = 0;
    for (int i = 1; i < (int)dane.size(); i++) {
        if (dane[i] > dane[i - 1]) {
            incLen++;
            decLen = 1;
            decStart = i;
        } else if (dane[i] < dane[i - 1]) {
            decLen++;
            incLen = 1;
            incStart = i;
        } else {
            incLen = 1;
            incStart = i;
            decLen = 1;
            decStart = i;
        }
        if (incLen > maxLen) {
            maxLen = incLen;
            maxStart = incStart;
            maxTyp = "rosnacy";
        }
        if (decLen > maxLen) {
            maxLen = decLen;
            maxStart = decStart;
            maxTyp = "malejacy";
        }
    }
    cout << "Najdluzszy monotoniczny: " << maxLen << " elementow (" << maxTyp << ")" << endl;
    cout << "Elementy:";
    for (int i = maxStart; i < maxStart + maxLen; i++) {
        cout << " " << dane[i];
    }
    cout << endl;
    return 0;
}
```

Weryfikacja:
- Rosnace: (5,8,12) dl=3, (3,4,6,10,11) dl=5, (1,5,9) dl=3
- Malejace: (12,9,7,3) dl=4, (11,8,2,1) dl=4
- Najdluzszy: rosnacy dl=5 (3,4,6,10,11), od pozycji 6
